def check_v_efficient(v, u_limit):
    # Precompute s(n) for n up to u_limit + 2*v
    s_vals = [0] * (u_limit + 2*v + 1)
    for n in range(1, u_limit + 2*v + 1):
        # Fast way to compute s(n)
        # s(n) = f(n) % 4
        # If n is odd, s(n) = n % 4
        # If n is even, s(n) = s(n // 2)
        if n % 2 != 0:
            s_vals[n] = n % 4
        else:
            s_vals[n] = s_vals[n // 2]

    for u in range(1, u_limit):
        all_ok = True
        for k in range(v):
            if s_vals[u+v+k] != s_vals[u+k]:
                all_ok = False
                break
        if all_ok:
            return True, u
    return False, None

